-- Fix auth_rls_initplan warnings by wrapping auth functions in SELECT

ALTER POLICY "Admins can update all profiles" ON "public"."profiles" USING ((EXISTS ( SELECT 1
   FROM user_roles
  WHERE ((user_roles.user_id = (select auth.uid())) AND (user_roles.role = 'admin'::app_role)))));
ALTER POLICY "Allow joining waiting duels" ON "public"."duels" USING (((status = 'waiting'::text) AND (opponent_id IS NULL) AND ((select auth.uid()) <> creator_id))) WITH CHECK ((((select auth.uid()) = opponent_id) AND (status = 'active'::text)));
